w('src/lib/public-data.ts','''import {supabase,configured} from './supabase/server';
import {serviceCatalog} from './service-catalog';
export async function publicData(){
 if(!configured())return {services:serviceCatalog,portfolio:[],testimonials:[],settings:{} as Record<string,string>,connected:false};
 const db=await supabase();
 const [s,p,t,w]=await Promise.all([db.from('services').select('*').eq('published',true).order('sort_order'),db.from('portfolio_projects').select('id,title,slug,client_name,category,industry,description,thumbnail_url,featured').eq('published',true).order('sort_order'),db.from('testimonials').select('id,name,company,quote').eq('published',true),db.from('website_settings').select('key,value').eq('is_public',true)]);
 if(s.error||p.error||t.error||w.error)throw new Error('Website content is temporarily unavailable.');
 return {services:s.data||[],portfolio:p.data||[],testimonials:t.data||[],settings:Object.fromEntries((w.data||[]).map(v=>[v.key,v.value])) as Record<string,string>,connected:true};
}''')
