w('src/app/(public)/services/[slug]/page.tsx','''import Link from 'next/link';import {notFound} from 'next/navigation';import {ArrowUpRight,Check} from 'lucide-react';import {publicData} from '@/lib/public-data';export default async function Service({params}:{params:Promise<{slug:string}>}){const{slug}=await params;const{services,portfolio}=await publicData();const s=services.find(v=>v.slug===slug);if(!s)notFound();return <main id="main" className="section-wrap page-main"><Link className="eyebrow" href="/services">SERVICES / {s.division==='digital'?'DIGITAL SOLUTIONS':'MARKETING & CREATIVE'}</Link><h1 className="page-title">{s.name}</h1><p className="page-intro">{s.description}</p><Link href={'/contact?service='+encodeURIComponent(s.name)} className="primary-link">Discuss your project <ArrowUpRight size={18}/></Link><div className="detail-columns">{[['Benefits',s.benefits],['Deliverables',s.deliverables],['Our workflow',s.workflow]].map(([title,body])=><section className="detail-panel" key={title}><h2>{title}</h2><ul>{String(body||'Defined together during project discovery.').split('\n').map(v=><li key={v}><Check size={16}/>{v}</li>)}</ul></section>)}</div>{s.show_pricing&&s.pricing&&<p className="pricing-note">{s.pricing}</p>}<section className="related-work"><h2>Related work</h2>{portfolio.filter(p=>(p.category||'').toLowerCase().includes(s.division)).length>0?portfolio.filter(p=>(p.category||'').toLowerCase().includes(s.division)).map(p=><Link key={p.id} href={'/portfolio/'+p.slug}>{p.title} <ArrowUpRight size={16}/></Link>):<p>Published case studies will appear in our portfolio. <Link href="/portfolio">Explore our work</Link></p>}</section></main>}''')
