w('src/app/(public)/portfolio/[slug]/page.tsx','''import {notFound} from 'next/navigation';import Link from 'next/link';import {supabase} from '@/lib/supabase/server';export default async function CaseStudy({params}:{params:Promise<{slug:string}>}){const{slug}=await params;const db=await supabase();const{data:p}=await db.from('portfolio_projects').select('*').eq('slug',slug).eq('published',true).single();if(!p)notFound();const{data:media}=await db.from('portfolio_media').select('*').eq('portfolio_project_id',p.id).order('sort_order');return <main id="main" className="section-wrap page-main"><Link href="/portfolio" className="eyebrow">OUR WORK / {p.category}</Link><h1 className="page-title">{p.title}</h1><p className="page-intro">{p.description}</p><div className="case-meta"><span>Client<strong>{p.client_name||'Confidential'}</strong></span><span>Industry<strong>{p.industry||'Not specified'}</strong></span>{p.project_date&&<span>Date<strong>{p.project_date}</strong></span>}</div>{p.thumbnail_url&&<img className="case-hero" src={p.thumbnail_url} alt={p.title}/>}<div className="detail-columns">{[['The challenge',p.challenge],['Our solution',p.solution],['The outcome',p.results]].filter(([,v])=>v).map(([k,v])=><section className="detail-panel" key={k}><h2>{k}</h2><p>{v}</p></section>)}</div><div className="case-meta"><span>Services<strong>{p.services_provided||'Not listed'}</strong></span><span>Technology<strong>{p.technologies||'Not listed'}</strong></span></div>{(media||[]).map(m=><figure key={m.id}><img className="case-hero" src={m.url} alt={m.alt} loading="lazy"/><figcaption>{m.alt}</figcaption></figure>)}{p.video_url&&/^https:\/\//.test(p.video_url)&&<a href={p.video_url} target="_blank" rel="noopener noreferrer" className="secondary-link">Watch project video ↗</a>}<Link href="/contact" className="primary-link">Start your project ↗</Link></main>}''')
w('src/components/inquiry-form.tsx','''"use client";import {useState} from 'react';import {useForm} from 'react-hook-form';import {zodResolver} from '@hookform/resolvers/zod';import {ArrowUpRight,CheckCircle2,LoaderCircle} from 'lucide-react';import {inquirySchema,type InquiryInput} from '@/lib/validation';
export function InquiryForm({services,selected='',connected}:{services:string[];selected?:string;connected:boolean}){const[success,setSuccess]=useState(false);const[error,setError]=useState('');const{register,handleSubmit,formState:{errors,isSubmitting},reset}=useForm<InquiryInput>({resolver:zodResolver(inquirySchema),defaultValues:{service:selected,website:'',consent:false}});async function submit(data:InquiryInput){setError('');try{const response=await fetch('/api/inquiry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Your inquiry could not be saved. Please try again.');setSuccess(true);reset()}catch(e){setError(e instanceof Error?e.message:'Your inquiry could not be saved.')}}
if(success)return <div className="inquiry-success" role="status"><CheckCircle2 size={42}/><h2>Good things start<br/>with a conversation.</h2><p>Your inquiry has been saved. The HEXA PLUS team can now review it and follow up using the contact details you provided.</p><button className="secondary-link" onClick={()=>setSuccess(false)}>Send another inquiry</button></div>;
const input=(key:keyof InquiryInput,label:string,props:React.InputHTMLAttributes<HTMLInputElement>={})=><label className="form-field"><span>{label}</span><input {...register(key)} {...props}/>{errors[key]&&<small className="field-error">{errors[key]?.message}</small>}</label>;
return <form className="inquiry-form" onSubmit={handleSubmit(submit)} noValidate><div className="form-grid">{input('name','Full name *',{autoComplete:'name',placeholder:'Your name'})}{input('company','Company name',{autoComplete:'organization',placeholder:'Your company'})}{input('email','Email *',{type:'email',autoComplete:'email',placeholder:'you@company.com'})}{input('phone','Phone / WhatsApp *',{type:'tel',autoComplete:'tel',placeholder:'+20 ...'})}<label className="form-field"><span>Service required *</span><select {...register('service')}><option value="">Choose a service</option>{services.map(s=><option key={s}>{s}</option>)}<option>Multiple services / not sure yet</option><option>Careers / introduction</option></select>{errors.service&&<small className="field-error">{errors.service.message}</small>}</label><label className="form-field"><span>Project budget</span><select {...register('budget')}><option value="">Let's discuss</option><option>Under EGP 25,000</option><option>EGP 25,000–75,000</option><option>EGP 75,000–150,000</option><option>EGP 150,000+</option></select></label><label className="form-field wide"><span>Project timeline</span><select {...register('timeline')}><option value="">Flexible / let's discuss</option><option>As soon as possible</option><option>1–3 months</option><option>3–6 months</option><option>6+ months</option></select></label><label className="form-field wide"><span>Tell us about your project *</span><textarea rows={5} placeholder="What are you working on, and how can we help?" {...register('description')}/>{errors.description&&<small className="field-error">{errors.description.message}</small>}</label></div><div className="honeypot" aria-hidden="true"><label>Website<input {...register('website')} tabIndex={-1} autoComplete="off"/></label></div><label className="consent"><input type="checkbox" {...register('consent')}/><span>I agree to the <a href="/privacy">privacy policy</a> and to being contacted about this inquiry.</span></label>{errors.consent&&<p className="field-error">{errors.consent.message}</p>}{!connected&&<p className="notice">Project inquiries will open when the secure database setup is complete. This form does not send or save messages yet.</p>}{error&&<p role="alert" className="field-error">{error}</p>}<button disabled={isSubmitting||!connected} className="primary-link" type="submit">{isSubmitting?<><LoaderCircle className="spin" size={18}/>Saving your inquiry</>:<>Send project inquiry <ArrowUpRight size={19}/></>}</button><p className="form-note">Your message goes straight to our private workspace. No mailing lists.</p></form>}
''')
w('src/lib/validation.ts','''import {z} from 'zod';import type {Module} from './modules';
export const inquirySchema=z.object({name:z.string().trim().min(2,'Please enter your full name.').max(200),company:z.string().trim().max(200).optional(),email:z.email('Please enter a valid email.').max(254),phone:z.string().trim().min(7,'Please enter a contact number.').max(80),service:z.string().trim().min(1,'Choose a service.').max(200),budget:z.string().max(100).optional(),timeline:z.string().max(100).optional(),description:z.string().trim().min(20,'Tell us a little more, at least 20 characters.').max(10000),website:z.string().max(0),consent:z.boolean().refine(v=>v,'Please accept the privacy policy.')});
export type InquiryInput=z.infer<typeof inquirySchema>;
export function moduleSchema(module:Module){const shape:Record<string,z.ZodType>= {};for(const f of module.fields){let rule:z.ZodType;if(f.type==='boolean')rule=z.boolean();else if(['number','money','percent'].includes(f.type))rule=z.number().int().min(f.min??0).max(f.max??(f.type==='percent'?10000:1000000000000));else if(f.type==='relation')rule=f.required?z.uuid():z.union([z.uuid(),z.null()]);else if(f.type==='select')rule=z.enum(f.options as [string,...string[]]);else if(f.type==='date')rule=f.required?z.iso.date():z.union([z.iso.date(),z.null()]);else if(f.type==='email')rule=f.required?z.email().max(254):z.union([z.email().max(254),z.null()]);else if(f.type==='url')rule=z.union([z.url().refine(v=>/^https:\/\//.test(v),'Only HTTPS URLs are accepted.'),z.null()]);else rule=f.required?z.string().trim().min(1).max(f.key==='description'?10000:4000):z.string().trim().max(10000).nullable();if(f.key==='slug')rule=z.string().min(1).max(160).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/,'Use lower-case words separated by hyphens.');shape[f.key]=rule;}return z.object(shape).strict()}
''')
w('src/app/(public)/contact/page.tsx','''import {publicData} from '@/lib/public-data';import {InquiryForm} from '@/components/inquiry-form';import {MapPin,ArrowUpRight} from 'lucide-react';export const metadata={title:'Start your project'};export default async function Contact({searchParams}:{searchParams:Promise<{service?:string}>}){const{services,settings,connected}=await publicData();const{service}=await searchParams;return <main id="main" className="section-wrap page-main contact-layout"><div className="contact-intro"><span className="eyebrow">LET'S START SOMETHING</span><h1 className="page-title">Big idea?<br/>First step?<br/><span>We're listening.</span></h1><p>Tell us where you are and where you want to go. We'll work out the right next step together.</p><div className="contact-location"><MapPin size={18}/>{settings.address||'Minya, Egypt'}</div>{settings.contact_email&&<a className="contact-method" href={'mailto:'+settings.contact_email}>{settings.contact_email}<ArrowUpRight size={16}/></a>}{settings.contact_phone&&<a className="contact-method" href={'tel:'+settings.contact_phone}>{settings.contact_phone}</a>}</div><InquiryForm services={services.map(s=>s.name)} selected={service} connected={connected}/></main>}''')
# Honest informational pages, content editable via public website_settings page_* keys.
pages={
'about':('About us','Different skills. One shared direction.','HEXA PLUS brings digital solutions and marketing services together in Minya, Egypt. We connect technology, creativity and business thinking to turn ideas into useful digital experiences.', [('Our vision','Help businesses move forward with technology and communication that work together.'),('Our mission','Build considered digital products, business solutions and brand experiences around clear goals.'),('What matters to us','Clarity, thoughtful work, honest communication and long-term usefulness.'),('How we think','Start with the business. Understand the people. Choose the right approach. Make every part connect.'),('Our capabilities','Software development, digital transformation, business systems, digital marketing, creative production, branding and growth strategy.'),('Our team','A connected approach across development, design, marketing and strategy. Team profiles will be published when approved.')]),
'industries':('Industries','Built around your business.','Every business has a different set of challenges. We start by understanding yours, rather than forcing it into a template.', [('Retail & commerce','Digital storefronts, customer journeys and marketing that connect discovery with purchase.'),('Professional services','Clear positioning, credible digital presence and better inquiry management.'),('Education & training','Accessible experiences, useful content and systems that support learning businesses.'),('Growing businesses','Operational systems, brand foundations and practical plans for the next stage.')]),
'process':('Our process','A clear path. Room for good ideas.','One shared plan, from the first conversation to launch and beyond.', [('01 / Discover','We listen, map the challenge, understand the audience and agree what success should mean.'),('02 / Define','We agree the scope, deliverables, responsibilities, timeline and commercial terms before production.'),('03 / Create','Design and development move through visible milestones, with feedback built into the process.'),('04 / Deliver & grow','We test, prepare the handover and launch carefully. Ongoing work is agreed separately and clearly.')]),
'careers':('Careers','Good work starts with good people.','Interested in working across technology, design and marketing? We value clear thinking, care for the details and people who enjoy making things together.', [('Open roles','No open roles are currently listed on this website. We do not collect applications through third-party recruitment forms here.'),('Introduce yourself','Use our contact form and select Careers / introduction. Tell us what you do and include a link to your work. Please do not send identity documents or sensitive personal details.')]),
'faq':('FAQ','A little clarity, before we start.','Answers to the questions that usually come first.', [('What does HEXA PLUS do?','We combine software development, business systems, digital transformation, marketing, branding and creative production.'),('Can we work on only one service?','Yes. The right scope might be a focused service or a connected group of services. We define it together.'),('How much will my project cost?','Cost depends on scope, complexity, delivery requirements and timeline. Send an inquiry for a project-specific discussion. No price is promised by this website.'),('How long does a project take?','We agree a realistic schedule after discovery. Timelines depend on scope, feedback, dependencies and available materials.'),('Where are you based?','Minya, Egypt. Use the inquiry form to discuss your project and collaboration needs.'),('Do you publish or run ads automatically?','No. Our internal marketing workspace records plans and results. Publishing and advertising require their own tools and explicit authorization.')]),
'privacy':('Privacy policy','Your information, handled with care.','This policy explains how the HEXA PLUS website uses information submitted through its project inquiry form.', [('What we collect','Your name, company, email, phone or WhatsApp number, requested service, optional budget and timeline, project description and your consent to follow up.'),('Why we use it','To review your inquiry, understand your requirements and contact you about the work you asked about. Submitting this form does not subscribe you to marketing.'),('Storage and access','Inquiries are stored in a Supabase database in Europe and are available to authorized HEXA PLUS staff through a private dashboard. Hosting and infrastructure providers process data as needed to operate the website.'),('Your choices','Do not include passwords, financial credentials, identity documents or sensitive information. You can ask the team to correct or delete your inquiry through the contact form, using the same email address.'),('Cookies','The public website does not use advertising cookies. The private dashboard uses necessary authentication cookies. Dashboard language and display preferences may be saved locally in your browser.'),('Retention and updates','Information should be retained only while needed for the inquiry or an agreed business relationship. This policy may be updated as the service changes. Updated: 21 November 2026.')]),
'terms':('Terms & conditions','A clear starting point.','These terms cover use of the HEXA PLUS website. Project-specific terms are agreed separately.', [('Website information','Service descriptions introduce our capabilities. They are not a binding quote, guarantee of results or commitment to a delivery date.'),('Project inquiries','Sending an inquiry does not create a contract or obligation to pay. Scope, fees, timing, ownership and support are agreed in a separate written project agreement.'),('Content and intellectual property','HEXA PLUS branding and original website content remain the property of their respective rights holders. Do not copy or misuse them without permission.'),('Acceptable use','Do not submit unlawful content, upload malicious files, attempt unauthorized access or interfere with the website.'),('Availability','We aim to keep the website useful and available, but uninterrupted access is not guaranteed. Free-tier hosting may pause when idle.'),('Questions','Use our contact form if you have a question about the website or these terms. Updated: 21 November 2026.')]),
}
for slug,(label,title,intro,sections) in pages.items():
 w('src/app/(public)/'+slug+'/page.tsx',f'''import Link from 'next/link';import {{publicData}} from '@/lib/public-data';export const metadata={{title:{json.dumps(label)}}};export default async function Page(){{const{{settings}}=await publicData();return <main id="main" className="section-wrap page-main"><span className="eyebrow">{label.upper()}</span><h1 className="page-title">{title}</h1><p className="page-intro">{intro}</p>{{settings.page_{slug}?<article className="prose-content">{{settings.page_{slug}}}</article>:<div className="editorial-grid">{''.join('<section className="detail-panel"><h2>'+h+'</h2><p>'+p+'</p></section>' for h,p in sections)}</div>}}<Link href="/contact" className="primary-link">Start a conversation ↗</Link></main>}}''')
w('src/app/api/inquiry/route.ts','''import {NextResponse} from 'next/server';import {inquirySchema} from '@/lib/validation';import {supabase,configured} from '@/lib/supabase/server';export async function POST(request:Request){try{const origin=request.headers.get('origin');if(origin&&new URL(request.url).host!==new URL(origin).host)return NextResponse.json({error:'Invalid request origin.'},{status:403});if(Number(request.headers.get('content-length')||0)>30000)return NextResponse.json({error:'Message too long.'},{status:413});if(!configured())return NextResponse.json({error:'The inquiry form is not connected yet. Please try again later.'},{status:503});const body=await request.text();if(body.length>30000)return NextResponse.json({error:'Message too long.'},{status:413});const parsed=inquirySchema.safeParse(JSON.parse(body));if(!parsed.success)return NextResponse.json({error:parsed.error.issues[0].message},{status:400});const db=await supabase();const{error}=await db.rpc('submit_inquiry',{payload:parsed.data});if(error)return NextResponse.json({error:error.message.includes('wait')?'Please wait before sending another inquiry.':'We could not save your inquiry. Please try again later.'},{status:400});return NextResponse.json({ok:true},{status:201});}catch{return NextResponse.json({error:'Please check your message and try again.'},{status:400})}}''')
w('src/app/api/health/route.ts','''import {NextResponse} from 'next/server';import {supabase,configured} from '@/lib/supabase/server';export async function GET(){if(!configured())return NextResponse.json({ready:false,database:'not configured'},{status:503});try{const db=await supabase();const{error}=await db.from('services').select('id').limit(1);return NextResponse.json({ready:!error},{status:error?503:200});}catch{return NextResponse.json({ready:false},{status:503})}}''')
